select id, host, log_ts, latency_ms, payload_json, get_json_object(payload_json, '$.duration') as duration_text, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries as retry_count, context['trace'] as trace, coalesce(context['region'], 'direct') as region_or_default from app_logs;
